/** The facts of a post in a column (author, date, minutes, views), then the related reading as links. */
import { type ReactNode } from "react";
import { Group } from "../primitives/group/group";
import { Link } from "../primitives/link/link";
import { LucideIcon } from "../primitives/lucide-icon/lucide-icon";
import { Stack } from "../primitives/stack/stack";
import { Text } from "../primitives/text/text";
import { tpl } from "../utils";
import type { Post } from "../blocks/post-card.types";
import type { PostExtras, PostSplitLabels } from "../blocks/post-split.types";

export type PostOutlineProps = {
  post: Post;
  extras: PostExtras;
  labels: PostSplitLabels;
};

export function PostOutline({ post, extras, labels }: PostOutlineProps) {
  return (
    <Stack gap="6" align="stretch" data-testid="post-outline">
      <Stack gap="2" align="start" className="text-muted-foreground">
        <Group gap="2" align="center">
          <LucideIcon name="user" size={16} />
          <Text size="sm">
            {post.author}
          </Text>
        </Group>
        <Group gap="2" align="center">
          <LucideIcon name="calendar" size={16} />
          <Text size="sm">
            {post.date}
          </Text>
        </Group>
        <Group gap="2" align="center">
          <LucideIcon name="clock" size={16} />
          <Text size="sm">
            {tpl(labels.minutes, post.minutes)}
          </Text>
        </Group>
        <Group gap="2" align="center">
          <LucideIcon name="eye" size={16} />
          <Text size="sm">
            {tpl(labels.views, extras.views)}
          </Text>
        </Group>
      </Stack>
      <Stack gap="2" align="stretch" className="border-t border-border pt-4">
        <Text size="xs" weight="medium" className="uppercase tracking-wide text-muted-foreground">
          {labels.related}
        </Text>
        {(extras.outline ?? []).map((l) => (
          <Link key={l.id} href="#/" size="sm" data-testid="post-link">
            <LucideIcon name="chevron-right" size={16} />
            {l.name}
          </Link>
        ))}
      </Stack>
    </Stack>
  );
}
